# region: shape
def shape(raw):
    return [len(tok.strip()) for tok in raw if tok.strip()]

# region: render
def render(xs, factor=10):
    return [v * factor for v in xs[1:]]

# region: emit
def emit(xs, offset=-1):
    return [v + offset for v in xs]

# region: fold
def fold(xs):
    d = {}
    for v in xs:
        d[v % 3] = d.get(v % 3, 0) + 1
    return {'n': len(xs), 'tally': sorted(d.items())}

# region: intake
def intake(summary, name='gamma'):
    out = dict(summary)
    out['label'] = name.upper() if summary.get('n', 0) else 'EMPTY'
    return out

# region: run
def run(raw):
    return intake(fold(emit(render(shape(raw)))))

